import { Category, ErrorEvent, Identity, PartyIdentification, UserEngagement } from '../events';
/**
Description: Click a button.
*/
export type ButtonClick = {
    events: Array<UserEngagement | Identity | PartyIdentification | ErrorEvent>;
}

export class ButtonClickBuilder {

    private buttonClick: ButtonClick = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private userEngagement!: UserEngagement;

    public withErrorEvent(errorEvent: ErrorEvent) : ButtonClickBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : ButtonClickBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : ButtonClickBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withUserEngagement(userEngagement: UserEngagement) : ButtonClickBuilder {
        this.userEngagement = userEngagement;
        return this;
    }

    public build() : ButtonClick {
        if(this.errorEvent) {
            this.buttonClick.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.buttonClick.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.buttonClick.events.push(this.partyIdentification);
        }
        if(this.userEngagement) {
            this.buttonClick.events.push(this.userEngagement);
        }

        return this.buttonClick;
    }
}
